import sqlite3
from typing import Optional
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("sprint-planner")
DB_PATH = "project_tracker.db"


@mcp.tool()
def move_task_to_sprint(task_id: int, target_sprint_id: Optional[int] = None) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute("SELECT sprint_id FROM tasks WHERE id = ?", (task_id,)).fetchone()
        if row is None:
            return {"ok": False, "error": f"Task {task_id} not found"}
        if target_sprint_id is not None:
            sprint = conn.execute("SELECT id FROM sprints WHERE id = ?", (target_sprint_id,)).fetchone()
            if sprint is None:
                return {"ok": False, "error": f"Sprint {target_sprint_id} not found"}
        conn.execute("UPDATE tasks SET sprint_id = ? WHERE id = ?", (target_sprint_id, task_id))
        conn.commit()
        return {"ok": True, "task_id": task_id, "from_sprint_id": row[0], "to_sprint_id": target_sprint_id}
    finally:
        conn.close()
